INSERT INTO `v1_5024097576dfa7874b4c86eb8438683f233272c91b82f3d657bfd4e12f42fda2` VALUES (1, 1, 0, 11, 130911, 10, "アオイさんですよね～っ！？\nグランドリームパークへようこそっ♪\n本日はおひとりさまですますか？", 0, 0, 66032, 5146066);
